import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_whitespace_comments_and_flags():
    lines = ["", " \t", "  # comment", " a , 2 , 0 ", "b,3, ", "c, 4 ,1"]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 3, "flagged": None},
        {"id": "c", "day": 4, "flagged": True},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,1", "x,day,1"])
def test_parse_errors_report_input_position(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# comment", "a,1,1", " ", bad_line])


def test_duplicate_ids_keep_last_input_record_then_sort():
    events = parse_transcript_log(["a,9,1", "b,2,1", "c,1,1", "a,2,0"])
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_daily_counts_include_zeros_and_respect_bounds():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,4,0", "e,5,1"])
    assert daily_flag_counts(events, 2, 4) == [2, 0, 0]
    assert daily_flag_counts(events, 4, 2) == []
