from safety_evals.metrics import flag_rate_by_group, flags_in_window, longest_flag_streak
from safety_evals.report import monitor_summary, top_flagged_groups


def test_trailing_window():
    assert flags_in_window([4, 2, 1], 0) == 0
    assert flags_in_window([4, 2, 1], 2) == 3
    assert flags_in_window([4, 2, 1], 4) == 7


def test_summary_includes_gaps_and_excludes_empty_groups():
    groups = {"a": [{"day": 1, "flagged": True}], "empty": [],
              "b": [{"day": 2, "flagged": True}, {"day": 5, "flagged": False}]}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rankings_and_rates():
    groups = {"z": [{"flagged": True}], "b": [], "a": [{"flagged": True}],
              "c": [{"flagged": None}]}
    assert top_flagged_groups(groups, 5) == ["a", "z", "c"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", None), ("c", 0.0), ("z", 1.0)
    ]


def test_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 0, 2, 3, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
